{
  "scenario_id": "sc-f69eea",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "Death",
      "years": [2017, 2024],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.07 AE/yr over 2017-2024; rise from ~0.64 to ~1.31, total ~+0.67, ending ~31% above baseline",
      "confidence": 0.9,
      "evidence": [
        "ae_death_by_year.csv shows a sustained monotonic rise from 2017 AE 0.637 to 2024 AE 1.307, including early ramp years 2018 0.660, 2019 0.784 and 2020 0.983",
        "summary.json Death overall_ae 1.004 masks the trend because early years 2015-2018 are ~0.63-0.70 while later years are above 1.0",
        "Empirical year-to-year SD of Death AE is ~0.26, materially above a Poisson 1/sqrt(expected claims) scale of ~0.035-0.065, so Poisson z-scores are not used for year flags"
      ],
      "recommended_action": "Investigate Death claims data and expected mortality assumptions: early-year claim capture/data quality, mortality table or expected count calibration, age/gender mix, claims definitions and large claims. Review pricing/valuation impact and check Death age/gender and benchmark files. CI, TPD and IP by-year A/E remain stable near 1.0 and appear clean; no action needed on those lines."
    }
  ]
}

